/// <summary>
/// Kurt Scerri - 03/03/2021
/// Replication of Microsoft class <c>BankPaymAdviceVendDP</c> due to internal class declarations
/// </summary>
[SRSReportParameterAttribute(classStr(METBankPaymAdviceContract))]
public final class METBankPaymAdviceVendDP extends SRSReportDataProviderPreProcessTempDB
{
    private METBankPaymAdviceVendV2Tmp bankPaymAdviceVendV2Tmp;

}

Method.Source:
[SRSReportDataSet(tableStr(METBankPaymAdviceVendTmp))]
public METBankPaymAdviceVendV2Tmp getBankPaymAdviceVendTmp()
{
    select bankPaymAdviceVendV2Tmp;
    return bankPaymAdviceVendV2Tmp;
}

    public void processReport() 
    {
        METBankPaymAdviceContract contract = this.parmDataContract() as METBankPaymAdviceContract;

        guid reportExecutionContext = this.createExecutionContext();

        LedgerJournalTrans ledgerJournalTrans = LedgerJournalTrans::findRecId(contract.parmLedgerJournalTransRecId(), false);

        METBankPaymAdviceReportGenerator reportGenerator = this.constructReportGenerator(ledgerJournalTrans, reportExecutionContext);

        reportGenerator.generateReportData(ledgerJournalTrans);

        this.copyReportDataToDPTmpTable(reportExecutionContext);

        reportGenerator.deleteReportData();
    }

    private METBankPaymAdviceReportGenerator constructReportGenerator(LedgerJournalTrans _ledgerJournalTrans, guid _reportExecutionContext)
    {
        METBankPaymAdviceReportGenerator reportGenerator = METBankPaymAdviceReportGenerator::newForJournal(_ledgerJournalTrans.JournalNum);

        // Need to process the report data on the same SQL thread as the report generation
        reportGenerator.getBankPaymAdviceTmp().setConnection(this.parmUserConnection());

        // The original design of the report generator relied on unique session id.
        // A unique, non-session based identifier is required for parallel and batch executions.
        reportGenerator.parmExecutionContext(_reportExecutionContext);

        return reportGenerator;
    }

    private void copyReportDataToDPTmpTable(guid _reportExecutionContext)
    {
        SysDaInsertObject insertObject = METBankPaymAdviceVendDPTransferQueryGenerator::newQuery(bankPaymAdviceVendV2Tmp, _reportExecutionContext);

        SysDaInsertStatement insertStatement = new SysDaInsertStatement();
        insertStatement.insert(insertObject);
    }
